import java.util.*;

public class MaxFlow {
    static class Edge {
        int to, capacity, flow, rev;
        Edge(int t, int c, int f, int r) {
            this.to = t;
            this.capacity = c;
            this.flow = f;
            this.rev = r;
        }
    }

    static final int MAXN = 121;
    static List<Edge>[] adj = new ArrayList[MAXN];
    static int[] level = new int[MAXN];
    static int[] start = new int[MAXN];
    static int s, t, n;
    static Queue<Integer> q = new LinkedList<>();

    static void addEdge(int v, int u, int cap) {
        adj[v].add(new Edge(u, cap, 0, adj[u].size()));
        adj[u].add(new Edge(v, 0, 0, adj[v].size() - 1));
    }

    static boolean bfs() {
        Arrays.fill(level, -1);
        level[s] = 0;
        q.clear();
        q.offer(s);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (Edge e : adj[v]) {
                if (level[e.to] < 0 && e.capacity - e.flow > 0) {
                    level[e.to] = level[v] + 1;
                    q.offer(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    static int pushFlow(int v, int flow) {
        if (v == t) return flow;
        for (int i = start[v]; i < adj[v].size(); i++) {
            Edge e = adj[v].get(i);
            if (level[e.to] == level[v] + 1 && e.capacity - e.flow > 0) {
                int pushed = pushFlow(e.to, Math.min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    adj[e.to].get(e.rev).flow -= pushed;
                    return pushed;
                }
            }
            start[v]++;
        }
        return 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int tbad = sc.nextInt();

        char[][] grid = new char[n][n];
        char[][] grid_b = new char[n][n];

        int px = -1, py = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = sc.next().charAt(0);
                if (grid[i][j] == 'Z') {
                    px = i;
                    py = j;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid_b[i][j] = sc.next().charAt(0);
            }
        }

        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }

        s = 0;
        t = 2 * n * n + 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int u = i * n + j + 1;
                if (grid[i][j] != '0') {
                    addEdge(s, u, grid[i][j] - '0');
                }
                if (grid_b[i][j] != '0') {
                    addEdge(u + n * n, t, grid_b[i][j] - '0');
                }
            }
        }

        int totalFlow = 0;
        while (bfs()) {
            Arrays.fill(start, 0);
            int pushed;
            while ((pushed = pushFlow(s, Integer.MAX_VALUE)) > 0) {
                totalFlow += pushed;
            }
        }
        System.out.println(totalFlow);
        sc.close();
    }
}
